static inline bool IsNullptr(const aclTensor *tensor, const char *name) 
{
  if (tensor == nullptr) {
    OP_LOGE(ACLNN_ERR_PARAM_NULLPTR, "Expected a proper Tensor but got null for argument %s.", name);
